15	function assertStorageCompatible(value: unknown): void {
16	  if (typeof value === "string" && value.includes("\0")) throw new Error("Source or reviewed mapping contains NUL characters that PostgreSQL cannot preserve");
17	  if (typeof value === "string") for (const character of value) {
18	    const codePoint = character.codePointAt(0)!;
19	    if (codePoint >= 0xd800 && codePoint <= 0xdfff) throw new Error("Source or reviewed mapping contains an unpaired Unicode surrogate; use valid Unicode text before continuing");
20	  }
21	  if (value && typeof value === "object") for (const [key, item] of Object.entries(value)) {
22	    assertStorageCompatible(key);
23	    assertStorageCompatible(item);
24	  }
25	}
26	
27	export const workbookScopeSchema = z.object({
28	  version: z.literal("xlsx-scope-v1"),
29	  tables: z.array(z.object({ sheetId: z.number().int().positive(), headerRow: z.number().int().positive(), endRow: z.number().int().positive() }).strict()
30	    .refine(table => table.endRow > table.headerRow, "A table needs data rows after its header")).min(1).max(100),
31	}).strict();
32	export type WorkbookScope = z.infer<typeof workbookScopeSchema>;
33	
