44	  balanceColumn: z.string().min(1).optional(),
45	  merchantColumn: z.string().min(1).optional(),
46	  categoryColumn: z.string().min(1).optional(),
47	  externalIdColumn: z.string().min(1).optional(),
48	  statusColumn: z.string().min(1).optional(),
49	  typeColumn: z.string().min(1).optional(),
50	  feeColumn: z.string().min(1).optional(),
51	  timestampTimezone: timezoneSchema.optional(),
52	  timestampTimezoneConfirmed: z.boolean().optional(),
53	  calendarTimezone: timezoneSchema.optional(),
54	  accountColumn: z.string().min(1).optional(),
55	  productColumn: z.string().min(1).optional(),
56	  accountRoutes: z.array(z.object({
