82	// IBANs and long account numbers become "••1234"; anything else is kept as written.
83	export function maskAccountNumber(value: string): string {
84	  const compact = value.replace(/\s/g, "");
85	  return /^[A-Z]{2}\d{2}[A-Z0-9]{10,30}$/i.test(compact) || /^\d{6,}$/.test(compact) ? `••${compact.slice(-4)}` : value;
86	}
