108	function knownStatement(rows: SourceRow[]) {
109	  const headers = Object.keys(rows[0] ?? {});
110	  return knownStatements.find(known => known.headers.every(column => headers.includes(column)));
111	}
112	
113	// The recognized statement format, shown so users can tell a known layout from a proposal.
114	export function detectStatementFormat(rows: SourceRow[]): string | undefined {
115	  return knownStatement(rows)?.format;
116	}
117	
118	// Same-named routes in several currencies get the currency appended, so each account reads distinctly.
119	function distinctRouteNames(routes: AccountRoute[]): AccountRoute[] {
120	  const counts = new Map<string, number>();
121	  for (const route of routes) counts.set(route.accountName, (counts.get(route.accountName) ?? 0) + 1);
122	  return routes.map(route => counts.get(route.accountName)! > 1 ? { ...route, accountName: `${route.accountName} ${route.currencyCode}` } : route);
123	}
124	
125	// Recognized statement formats avoid a provider round trip; every proposal still needs review.
126	// Account names default to bank/product plus the last account digits, never the filename or a full IBAN.
127	export function proposeKnownStatementMapping(rows: SourceRow[], accountName: string, currencyCode: string): ImportMapping | undefined {
128	  const known = knownStatement(rows);
129	  if (!known) return undefined;
130	  const proposed = proposeAccountRoutes(rows, { ...known.mapping, accountName: known.routeName({ currencyCode }) || accountName, currencyCode });
131	  return proposed.accountRoutes ? { ...proposed, accountRoutes: distinctRouteNames(proposed.accountRoutes.map(route => ({ ...route, accountName: known.routeName(route) }))) } : proposed;
132	}
