190	function workbookRows(workbook: ExcelJS.Workbook, input?: WorkbookScope, legacy = false): SourceRow[] {
191	  if (!workbook.worksheets.length) throw new Error("Workbook has no sheets");
192	  if (!input && !legacy && workbook.worksheets.length !== 1) throw new Error("Select the included worksheets and table scope before importing");
193	  const scope = input ? workbookScopeSchema.parse(input) : { version: "xlsx-scope-v1", tables: [{ sheetId: workbook.worksheets[0].id, headerRow: 1, endRow: workbook.worksheets[0].rowCount }] };
194	  const selected = scope.tables.map(table => {
195	    const sheet = workbook.getWorksheet(table.sheetId);
196	    if (!sheet || table.endRow > sheet.rowCount || !sheet.rowCount) throw new Error("Selected worksheet table is unavailable or empty");
197	    return { ...table, sheet, sheetIndex: workbook.worksheets.indexOf(sheet) };
198	  }).sort((a, b) => a.sheetIndex - b.sheetIndex || a.headerRow - b.headerRow);
199	  const rows: SourceRow[] = [];
200	  let previous: typeof selected[number] | undefined;
201	  let sharedHeaders: string[] | undefined;
202	  for (const table of selected) {
203	    if (previous?.sheet.id === table.sheet.id && table.headerRow <= previous.endRow) throw new Error("Selected workbook tables overlap");
204	    previous = table;
205	    const header = table.sheet.getRow(table.headerRow);
206	    const headers = Array.from({length: legacy ? table.sheet.columnCount : header.cellCount}, (_, index) => cellText(header.getCell(index + 1)).trim());
207	    if (!headers.length || headers.some(value => !value || (!legacy && value.startsWith("__moneo_csv_"))) || new Set(headers).size !== headers.length) throw new Error("Missing, duplicate or reserved XLSX headers");
