434	// Explicit merchant columns win (normalized, canonicalized when known).
435	// Without one, only a tiny explicit fragment table may infer a name;
436	// otherwise returns null (unknown merchant, import continues).
437	export function resolveMerchantName(explicit: string | undefined, description: string): string | null {
