480	export function inspectRows(rows: SourceRow[], input: unknown) {
481	  const mapping = validateMapping(input, rows);
482	  const decisions = new Map((mapping.rowDecisions ?? []).map(decision => [decision.rowNumber, decision]));
483	  const excludedRows: { rowNumber: number; sourceRow: SourceRow; reason: string }[] = [];
484	  const unresolvedRows: { rowNumber: number; sourceRow: SourceRow; reason: "invalid_row"; message: string }[] = [];
485	  const mapped: MappedRow[] = reviewedSourceRows(rows, mapping).flatMap((sourceRow, index): MappedRow[] => {
486	    if (!sourceRow) {
487	      const decision = decisions.get(index + 2)!;
488	      if (decision.action === "exclude") excludedRows.push({ rowNumber: index + 2, sourceRow: rows[index], reason: decision.reason });
489	      return [];
490	    }
491	    try {
492	      const header = (name: string) => Object.keys(sourceRow).find(key => key.trim().toLowerCase() === name);
493	      const typeColumn = mapping.typeColumn ?? header("type");
494	      const feeColumn = mapping.feeColumn ?? header("fee");
495	      const decision = decisions.get(index + 2);
496	      const evidence = mapping.workbookScope && rows[index].__moneo_csv_xlsx_source ? JSON.parse(rows[index].__moneo_csv_xlsx_source) as {cells: Record<string,{value: unknown}>} : undefined;
497	      const numericCell = (column: string) => {
498	        if (decision?.action === "correct" && Object.hasOwn(decision.values, column)) return undefined;
499	        const original = evidence?.cells[column]?.value;
500	        const value = original && typeof original === "object" && "result" in original ? original.result : original;
501	        return typeof value === "number" ? value : undefined;
502	      };
503	      if (rows[index][csvIssueColumn]) {
504	        const decision = decisions.get(index + 2);
505	        if (decision?.action !== "correct") throw new Error(`Source field mismatch (${rows[index][csvIssueColumn]}): explicitly review mapped cells or exclude this observation`);
506	        const columns = Object.entries(mapping).filter(([key, value]) => key.endsWith("Column") && typeof value === "string").map(([, value]) => value as string);
507	        for (const name of ["type", "fee"]) {
508	          const column = Object.keys(rows[index]).find(key => key.trim().toLowerCase() === name);
509	          if (column) columns.push(column);
510	        }
511	        if (columns.some(column => !Object.hasOwn(decision.values, column))) throw new Error("Source field mismatch: review all mapped cells before accepting the corrected interpretation");
512	      }
513	      if (evidence) {
514	        for (const column of [mapping.amountColumn, mapping.debitColumn, mapping.creditColumn, mapping.balanceColumn, feeColumn].filter((name): name is string => Boolean(name))) {
515	          const value = numericCell(column);
516	          if (value === undefined) continue;
517	          const significantDigits = String(value).split(/e/i)[0].replace(/[-.]/g, "").replace(/^0+/, "").length;
518	          if (!Number.isFinite(value) || Math.abs(value) > Number.MAX_SAFE_INTEGER || significantDigits > 15)
519	            throw new Error(`Unsafe XLSX numeric precision in ${column}: review an exact source string or explicitly correct/exclude the observation`);
520	        }
521	      }
522	      const description = sourceRow[mapping.descriptionColumn]?.trim();
523	      if (!description) throw new Error("Missing description");
524	      // PostgreSQL length counts Unicode code points, rather than UTF-16 units.
525	      if (Array.from(description).length > 500) throw new Error("Description exceeds 500 characters");
526	      // The RPC has an 11 MB JSON record boundary. Account for escaped original
527	      // evidence, JSONB separator spaces and duplicated external IDs, reserving
528	      // 1 MB for bounded fields.
529	      if (new TextEncoder().encode(JSON.stringify({ originalRow: rows[index],
530	        externalId: mapping.externalIdColumn ? sourceRow[mapping.externalIdColumn] : null })).byteLength + 2 * Object.keys(rows[index]).length > 10_000_000)
531	        throw new Error("Source evidence exceeds the import record limit; review an explicit exclusion");
532	      const currencyCode = (mapping.currencyColumn ? sourceRow[mapping.currencyColumn] : mapping.currencyCode).trim().toUpperCase();
533	      if (!/^[A-Z]{3}$/.test(currencyCode)) throw new Error("Invalid currency");
534	      const accountValue = mapping.accountColumn ? sourceRow[mapping.accountColumn]?.trim() : undefined;
535	      const productValue = mapping.productColumn ? sourceRow[mapping.productColumn]?.trim() : undefined;
536	      const routes = mapping.accountRoutes?.filter(route => route.currencyCode === currencyCode &&
537	        route.accountValue === accountValue && route.productValue === productValue);
538	      if ((mapping.accountColumn || mapping.productColumn || mapping.accountRoutes) && routes?.length !== 1)
539	        throw new Error("Review account routing: each account/product/currency requires exactly one route");
540	      const accountName = routes?.[0]?.accountName ?? mapping.accountName;
541	      const money = (column: string) => parseAmountMinor(sourceRow[column] ?? "", currencyCode, numericCell(column) === undefined ? mapping.numericConvention : "decimal-dot");
542	      let amountMinor: bigint;
543	      if (mapping.amountColumn) {
544	        amountMinor = money(mapping.amountColumn);
545	        if (mapping.amountSign === "outflow-positive") amountMinor = -amountMinor;
546	      } else {
547	        const debit = sourceRow[mapping.debitColumn!] ?? "";
548	        const credit = sourceRow[mapping.creditColumn!] ?? "";
549	        if (Boolean(debit.trim()) === Boolean(credit.trim())) throw new Error("Expected exactly one debit or credit value");
550	        amountMinor = credit.trim() ? money(mapping.creditColumn!) : -money(mapping.debitColumn!);
551	        if ((credit.trim() && amountMinor < 0n) || (debit.trim() && amountMinor > 0n))
552	          throw new Error("Debit and credit values must be positive");
553	        if (amountMinor === 0n) throw new Error("Zero debit or credit");
554	      }
555	      databaseMinor(amountMinor);
556	      const sourceType = typeColumn ? sourceRow[typeColumn]?.trim() : undefined;
557	      const type = sourceType?.toLowerCase();
558	      const reviewReasons: string[] = [];
559	      let kind: MappedRow["kind"] = "ordinary";
560	      if (type === "transfer" || type === "transfer (realtime)") reviewReasons.push("source_transfer");
561	      else if (type === "exchange") reviewReasons.push("source_exchange");
562	      else if (type === "card refund") {
563	        if (amountMinor > 0n) kind = "refund";
564	        else reviewReasons.push("refund_sign");
565	      } else if (type && type !== "card payment" && !(type === "debit" && amountMinor < 0n)) reviewReasons.push("source_type");
566	      let feeMinor: bigint | undefined;
567	      if (feeColumn && sourceRow[feeColumn]?.trim()) {
568	        try { feeMinor = money(feeColumn); }
569	        catch (error) {
570	          if (error instanceof Error && error.message.includes("numeric convention")) throw error;
571	          reviewReasons.push("fee_semantics");
572	        }
573	      }
574	      if (feeMinor !== undefined && feeMinor !== 0n) reviewReasons.push("fee_semantics");
575	      const sourceDate = sourceRow[mapping.dateColumn] ?? "";
576	      const postedDate = parseDate(sourceDate, mapping.dateFormat);
577	      const postedAt = mapping.dateFormat === "iso" ? parseTimestamp(sourceDate, mapping.timestampTimezone) : undefined;
578	      return [{
579	        rowNumber: index + 2,
580	        accountName,
581	        postedOn: postedAt ? calendarDate(postedAt, mapping.calendarTimezone) : postedDate,
582	        ...(postedAt ? { postedAt } : {}),
583	        ...(mapping.calendarTimezone ? { calendarTimezone: mapping.calendarTimezone } : {}),
584	        description,
585	        amountMinor,
586	        currencyCode,
587	        status: mapping.statusColumn ? parseTransactionStatus(sourceRow[mapping.statusColumn]) : "posted",
588	        kind, reviewReasons,
589	        ...(sourceType ? { sourceType } : {}),
590	        ...(feeMinor !== undefined ? { feeMinor } : {}),
591	        sourceRow: rows[index],
592	        ...(mapping.merchantColumn && sourceRow[mapping.merchantColumn]?.trim() ? { merchant: sourceRow[mapping.merchantColumn].trim() } : {}),
593	        ...(mapping.categoryColumn && sourceRow[mapping.categoryColumn]?.trim() ? { category: sourceRow[mapping.categoryColumn].trim() } : {}),
594	        ...(mapping.externalIdColumn && sourceRow[mapping.externalIdColumn]?.trim() ? { externalId: sourceRow[mapping.externalIdColumn].trim() } : {}),
595	        ...(mapping.balanceColumn && sourceRow[mapping.balanceColumn]?.trim() ? { balanceMinor: money(mapping.balanceColumn) } : {}),
596	      }];
597	    } catch (error) {
598	      unresolvedRows.push({ rowNumber: index + 2, sourceRow: rows[index], reason: "invalid_row",
599	        message: `Row ${index + 2}: ${error instanceof Error ? error.message : String(error)}` });
600	      return [];
601	    }
602	  });
603	  const groups = new Map<string, MappedRow[]>();
604	  for (const row of mapped) {
605	    const key = JSON.stringify([row.accountName, row.currencyCode]);
606	    const group = groups.get(key) ?? [];
607	    group.push(row);
608	    groups.set(key, group);
609	    if (row.feeMinor !== undefined && row.feeMinor !== 0n) row.feeEvidence = { treatment: "unknown" };
610	  }
611	  for (const group of groups.values()) {
612	    // Missing/excluded observations cannot establish adjacent statement balances.
613	    if (unresolvedRows.length || excludedRows.length) continue;
614	    if (group.some(row => !row.postedAt)) continue;
615	    group.sort((a, b) => a.postedAt!.localeCompare(b.postedAt!));
616	    for (let index = 1; index < group.length; index++) {
617	      const row = group[index], previous = group[index - 1], next = group[index + 1];
618	      if (!row.feeEvidence || row.status !== "posted" || previous.status !== "posted" || row.balanceMinor === undefined || previous.balanceMinor === undefined ||
619	          row.postedAt === previous.postedAt || row.postedAt === next?.postedAt) continue;
620	      const deltaMinor = row.balanceMinor - previous.balanceMinor;
621	      const fee = row.feeMinor! < 0n ? -row.feeMinor! : row.feeMinor!;
622	      row.feeEvidence = { treatment: deltaMinor === row.amountMinor ? "included" : deltaMinor === row.amountMinor - fee ? "additional" : "unknown", deltaMinor, previousRowNumber: previous.rowNumber };
623	    }
624	  }
625	  return { mapped, unresolvedRows, excludedRows, correctedRows: mapped.filter(row => decisions.get(row.rowNumber)?.action === "correct").length };
626	}
627	
628	export function previewImport(rows: SourceRow[], input: unknown) {
629	  const mapping = validateMapping(input, rows);
630	  const { mapped, unresolvedRows, excludedRows, correctedRows } = inspectRows(rows, mapping);
631	  const dates = mapped.map((row) => row.postedOn).sort();
632	  return {
633	    accountName: mapping.accountName,
634	    currencyCode: mapping.currencyCode,
635	    accounts: Array.from(mapped.reduce((groups, row) => {
636	      const key = JSON.stringify([row.accountName, row.currencyCode]);
637	      const group = groups.get(key) ?? { accountName: row.accountName, currencyCode: row.currencyCode, rows: 0 };
638	      group.rows++;
639	      groups.set(key, group);
640	      return groups;
641	    }, new Map<string, { accountName: string; currencyCode: string; rows: number }>()).values()),
642	    totalRows: rows.length,
643	    acceptedRows: mapped.length,
644	    unresolvedRows,
645	    excludedRows,
646	    correctedRows,
647	    pendingRows: mapped.filter((row) => row.status === "pending").length,
648	    postedRows: mapped.filter((row) => row.status === "posted").length,
649	    classificationReviewRows: mapped.filter(row => row.reviewReasons.length > 0).length,
650	    timestampReviewRequired: reviewedSourceRows(rows, mapping).some(row => row && /[ T]\d{2}:\d{2}:\d{2}(?:\.\d{1,3})?$/.test(row[mapping.dateColumn]?.trim() ?? "")),
651	    dateRange: { from: dates[0], to: dates[dates.length - 1] },
652	    examples: mapped.slice(0, 5),
